import fs from 'node:fs';import assert from 'node:assert/strict';import {DatabaseSync} from 'node:sqlite';
import {handleWorkspace} from '../preview-server/workspace-service.mjs';
const sqlite=new DatabaseSync(':memory:');sqlite.exec('PRAGMA foreign_keys=ON;');sqlite.exec(fs.readFileSync('preview-server/drizzle/0000_futuristic_vertigo.sql','utf8'));let queries=0;
const DB={prepare(sql){return {bind(...args){return {async first(){queries++;return sqlite.prepare(sql).get(...args)||null;},async all(){queries++;return {results:sqlite.prepare(sql).all(...args)};},async run(){queries++;const result=sqlite.prepare(sql).run(...args);return {meta:{changes:Number(result.changes)}};}};}};}};
let time=1000000,nonce=0,checks=0;
async function call(user,path,method='GET',value,headers={}){const request=new Request('https://private.example/api/workspace'+path,{method,headers:{...(value!==undefined?{'content-type':'application/json'}:{}),...headers},...(value!==undefined?{body:JSON.stringify(value)}:{})}),response=await handleWorkspace(request,{DB},user,{now:()=>time,randomId:()=>('record-'+(++nonce))});const data=await response.json();assert.equal(response.headers.get('cache-control'),'no-store');checks++;return {status:response.status,data};}
function status(result,value){assert.equal(result.status,value,JSON.stringify(result.data));checks++;return result.data;}
status(await call(null,'/session'),401);assert.equal(queries,0);checks++;
status(await call('owner','/session','GET',undefined,{origin:'https://other.example'}),403);
status(await call('owner','/session'),200);
let data=status(await call('owner','/sync'),200);assert.equal(data.revision,0);checks++;
const backup={schema:'marine-tools-backup',version:1,entries:{'mt.profile':JSON.stringify({name:'QA VESSEL'})}};
status(await call('owner','/sync','PUT',{backup}),428);
data=status(await call('owner','/sync','PUT',{backup},{'if-match':'0'}),200);assert.equal(data.revision,1);checks++;
status(await call('owner','/sync','PUT',{backup},{'if-match':'0'}),409);
assert.equal(status(await call('other','/sync'),200).backup,null);checks++;
status(await call('owner','/sync','PUT',{backup:{...backup,entries:{password:'"secret"'}}},{'if-match':'1'}),400);
const races=await Promise.all([call('owner','/sync','PUT',{backup},{'if-match':'1'}),call('owner','/sync','PUT',{backup},{'if-match':'1'})]);assert.deepEqual(races.map(r=>r.status).sort(),[200,409]);checks++;
status(await call('owner','/sync','DELETE',undefined,{'if-match':'1'}),409);
status(await call('owner','/sync','DELETE',undefined,{'if-match':'2'}),200);
assert.equal(status(await call('owner','/sync'),200).revision,3);checks++;
assert.equal(status(await call('owner','/sync'),200).backup,null);checks++;
status(await call('owner','/sync','PUT',{backup},{'if-match':'0'}),409);
status(await call('owner','/sync','PUT',{backup},{'if-match':'3'}),200);
status(await call('owner','/sync','PUT',{backup},{'if-match':'1'}),409);
const cls=status(await call('teacher','/classes','POST',{name:'QA Engineering'}),201);assert.ok(cls.joinCode);checks++;
status(await call('student','/classes/'+cls.id),403);
status(await call('student','/classes/join','POST',{code:'wrong',displayName:'QA Learner'}),404);
status(await call('student','/classes/join','POST',{code:cls.joinCode,displayName:'QA Learner'}),200);
data=status(await call('student','/classes/'+cls.id),200);assert.equal(data.joinCode,undefined);assert.equal(data.members.length,0);checks+=2;
status(await call('student','/classes/'+cls.id,'DELETE'),403);
const item={id:'qa-question',prompt:'Find 2 + 3.',expected:5,unit:'',chapter:1,steps:['2 + 3 = 5'],tolerance:0,relativeTolerance:0};
status(await call('student','/classes/'+cls.id+'/assignments','POST',{title:'Not allowed',items:[item]}),403);
const assignment=status(await call('teacher','/classes/'+cls.id+'/assignments','POST',{title:'Addition practice',items:[item],dueAt:time+10000}),201);
data=status(await call('student','/assignments/'+assignment.id),200);assert.equal(data.items[0].expected,undefined);assert.equal(data.items[0].steps,undefined);checks+=2;
status(await call('outsider','/assignments/'+assignment.id),403);
status(await call('teacher','/assignments/'+assignment.id+'/submissions','POST',{answers:{'qa-question':'5'}}),403);
data=status(await call('student','/assignments/'+assignment.id+'/submissions','POST',{answers:{'qa-question':'4'}}),200);assert.equal(data.score,0);assert.equal(data.grades[0].expected,5);checks+=2;
time+=20000;data=status(await call('student','/assignments/'+assignment.id+'/submissions','POST',{answers:{'qa-question':'5'}}),200);assert.equal(data.score,1);assert.equal(data.late,true);checks+=2;
data=status(await call('student','/assignments/'+assignment.id),200);assert.equal(data.submission.attempts,2);assert.equal(data.items[0].expected,5);checks+=2;
status(await call('student','/assignments/'+assignment.id+'/submissions'),403);
data=status(await call('teacher','/assignments/'+assignment.id+'/submissions'),200);assert.equal(data.submissions[0].display_name,'QA Learner');assert.equal(data.submissions[0].score,1);checks+=2;
// Class and assignment deletion enforce the same owner/member boundary.
status(await call('student','/assignments/'+assignment.id,'DELETE'),403);
status(await call('teacher','/classes/'+cls.id+'/assignments','POST',{title:'Invalid identity',items:[{id:'constructor',chapter:1,prompt:'Fixture',expected:1,unit:'m',steps:['Fixture']}]}),400);
status(await call('student','/classes/'+cls.id+'/membership','DELETE'),200);
status(await call('student','/assignments/'+assignment.id),403);
assert.equal(sqlite.prepare('SELECT COUNT(*) AS n FROM assignment_submissions').get().n,0);checks++;
status(await call('teacher','/assignments/'+assignment.id,'DELETE'),200);
status(await call('teacher','/classes/'+cls.id,'DELETE'),200);
status(await call('student','/assignments/'+assignment.id),404);assert.equal(sqlite.prepare('SELECT COUNT(*) AS n FROM assignment_submissions').get().n,0);checks++;
sqlite.close();console.log(JSON.stringify({status:'PASS',checks,sqlQueries:queries,scope:'Real SQLite schema, owner-isolated sync, revision races, CSRF, membership/teacher checks, hidden answers until submission, server grading and cascade deletion. Auth identities are test fixtures, not production sign-in.'}));
